   // Configurar el tamaño de la matriz resultante
   result.filas = filasA;
   result.columnas = columnasB;
   result.valores.valores_len = filasA * columnasB;
   result.valores.valores_val = (double *)malloc(result.valores.valores_len * sizeof(double));


   if (result.valores.valores_val == NULL) {
       printf("[ERROR] No se pudo asignar memoria para la matriz resultante\n");
       result.filas = 0;
       result.columnas = 0;
       result.valores.valores_len = 0;
       return &result;
   }


   // Inicializar la matriz resultante en 0
   for (int i = 0; i < filasA * columnasB; i++) {
       result.valores.valores_val[i] = 0.0;
   }


   // Multiplicación de matrices
   for (int i = 0; i < filasA; i++) {
       for (int j = 0; j < columnasB; j++) {
           for (int k = 0; k < columnasA; k++) {
               int index_result = i * columnasB + j;
               int index_A = i * columnasA + k;
               int index_B = k * columnasB + j;


               if (index_A >= mat.A.valores.valores_len || index_B >= mat.B.valores.valores_len) {
                   printf("[ERROR] Acceso fuera de rango en A o B (i=%d, j=%d, k=%d)\n", i, j, k);
                   continue;
               }


               result.valores.valores_val[index_result] +=
                   mat.A.valores.valores_val[index_A] * mat.B.valores.valores_val[index_B];
           }
       }
   }


